def main():
 O.mkdir(exist_ok=True);(O/'frames').mkdir(exist_ok=True)
 d=json.loads((SRC/'receipt.json').read_text(encoding='utf-8'));s=json.loads((SRC/'silhouette_and_source/receipt.json').read_text(encoding='utf-8'))
 assert d['frames']==s['training_frames']==49 and s['diagnostic_source_frames']==199 and d['training_updates']==s['training_updates']==0
 for raw in [89,107,128,137]:
  fid=f'0008{raw:03d}';shutil.copy2(SRC/'fullframes'/f'{fid}_exposure.png',O/'frames'/f'raw{raw}_exposure.png')
  for key in ['gt','static','dynamic']:
   shutil.copy2(W/'GN11_stage1_full49'/fid/f'{key}.png',O/'frames'/f'raw{raw}_{key}.png')
 for raw in [138,160,198]:shutil.copy2(SRC/'silhouette_and_source/source_fullframes'/f'raw{raw}.jpg',O/'frames'/f'source_raw{raw}.jpg')
 # Evidence colour covers body pixels in the complete observed image, never a crop.
 evidence=np.load(SRC/'silhouette_and_source/evidence.npz');count=evidence['exposure'].sum(0);rgb=np.asarray(Image.open(W/'GN11_stage1_full49/0008128/gt.png')).copy()
 for row in s['rows']:
  pix=np.array(row['pixels_xy']);values=count[row['start']:row['end']];color=np.where((values>=3)[:,None],[40,225,125],np.where((values>0)[:,None],[255,195,45],[255,50,50]))
  rgb[pix[:,1],pix[:,0]]=np.rint(.5*rgb[pix[:,1],pix[:,0]]+.5*color).astype(np.uint8)
 Image.fromarray(rgb).resize((960,640),Image.Resampling.NEAREST).save(O/'frames/raw128_silhouette_exposure.png')
 footprints=[r for r in d['footprint_summaries'] if r['anchor_raw']==128 and r['anchor_image_inside_fraction']>.5]
 motion=''.join(f"<tr><td>a{r['actor']}</td><td>{'左侧对向车道' if r['actor'] in [5,26,18] else '自车道前方'}</td><td>{r['path_length_world_m']:.2f} m</td><td>{r['visible_mask_frames']}/49</td></tr>" for r in d['motion'])
 exposure=''.join(f"<tr><td>a{r['actor']}</td><td>{r['valid_ground_queries']}/{r['body_pixels']}（{pc(r['valid_body_ground_fraction'])}）</td><td>{pc(r['exposure_49']['never_exposed_fraction'])}</td><td>{pc(r['exposure_49']['at_least_3_frames_fraction'])}</td><td>{r['exposure_49']['median_exposed_frames']:.0f}</td></tr>" for r in s['rows'])
 physical=''.join(f"<tr><td>a{r['actor']}</td><td>{r['non_vehicle_exposure']['median_exposed_frames']:.0f}</td><td>{pc(r['actual_LiDAR_support_0p25m']['never_exposed_fraction'])}</td><td>{r['actual_LiDAR_support_0p25m']['median_exposed_frames']:.1f}</td></tr>" for r in footprints)
 longer=''.join(f"<tr><td>a{r['actor']}</td><td>{pc(r['box_only_training49_opportunities']['at_least_3_frames_fraction'])}</td><td>{pc(r['box_only_full199_opportunities']['at_least_3_frames_fraction'])}</td><td>raw{r['best_outside49_box_only_frame'][0]}（单帧覆盖{pc(r['best_outside49_box_only_frame'][1])}）</td></tr>" for r in s['rows'])
 summary={k:v for k,v in d.items() if k!='footprint_summaries'};summary['raw128_footprints']=footprints;summary['silhouette_source']={k:v for k,v in s.items() if k not in ['rows','source_frames']};summary['silhouette_rows']=[{k:v for k,v in r.items() if k!='pixels_xy'} for r in s['rows']];summary['source_frames']=s['source_frames']
 (O/'evidence_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
 shutil.copy2(SRC/'receipt.json',O/'footprint_evidence.json');shutil.copy2(SRC/'silhouette_and_source/receipt.json',O/'silhouette_evidence.json')
 diagram='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1120 160"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#9cc9ed"/></marker></defs><g fill="#17384d" stroke="#78a7c8"><rect x="5" y="20" width="240" height="110" rx="10"/><rect x="290" y="20" width="270" height="110" rx="10"/><rect x="605" y="20" width="240" height="110" rx="10"/><rect x="890" y="20" width="225" height="110" rx="10"/></g><g stroke="#9cc9ed" stroke-width="3" marker-end="url(#arrow)"><path d="M245 75H285M560 75H600M845 75H885"/></g><g fill="#edf7ff" font-family="sans-serif" font-size="18" text-anchor="middle"><text x="125" y="48">原始49帧与物理测量</text><text x="125" y="78">RGB / 位姿 / 标定 / LiDAR</text><text x="125" y="108">真实车辆框与分割掩码</text><text x="425" y="48">同一世界坐标路面查询</text><text x="425" y="78">实测平面近似 + 跨帧投影</text><text x="425" y="108">车辆遮挡检查</text><text x="725" y="48">曝光与几何支撑</text><text x="725" y="78">49帧曝光机会 / LiDAR</text><text x="725" y="108">199帧只读候选检查</text><text x="1002" y="48">解释左右车道差异</text><text x="1002" y="78">缺观测 / 已曝光误差</text><text x="1002" y="108">阴影残留另行区分</text></g></svg>'''
 (O/'architecture.svg').write_text(diagram,encoding='utf-8')
 now=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(timespec='seconds')
 page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>左右车道：道路观测与删车残影核查</title><style>body{{margin:0;background:#0b1520;color:#e1eff9;font:16px/1.7 system-ui,"Microsoft YaHei"}}main{{max-width:1280px;margin:auto;padding:24px}}section{{padding:20px;background:#142a3b;border-radius:10px;margin:18px 0}}a{{color:#83d1ff}}table{{border-collapse:collapse;width:100%}}th,td{{border:1px solid #416078;padding:9px;text-align:left}}img{{width:100%;height:auto}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.good{{color:#71e8ab}}.bad{{color:#ff8e86}}.small{{font-size:14px;color:#b2c7d8}}button,select{{font:inherit;padding:6px;background:#23435b;color:#fff;border:1px solid #527c99;border-radius:5px}}@media(max-width:800px){{.grid{{grid-template-columns:1fr}}main{{padding:12px}}table{{font-size:13px}}}}</style><main>
<h1>左右车道的差异：缺少道路观测是更有力的主导解释</h1><p>{now} · 只读CPU核查 · 训练更新0 · A/B输入及训练保持原样</p><p><a href="../index.html">实验状态</a> · <a href="../results.html">完整49帧同步视频</a> · <a href="evidence_summary.json">精简数值证据</a></p>
<section><p><b>修订判断：</b>当前49帧中，自车道删车后背景受观测不足的限制远大于左侧近处车道。静态层有车形，并不能单凭外观判断为高斯身份错分。更符合证据的描述是：动态主体已承担车辆重建，但被遮挡路面没有可靠地重建出来；少数已有曝光机会的区域仍有明显误差，阴影也没有随车辆删除。</p><p>这是主要解释的证据排序，不是因果贡献百分比，也不等于“所有Gaussian归属已经正确”。</p><img src="architecture.svg" alt="原始测量经世界路面投影与遮挡检查，得到曝光次数、LiDAR支撑和左右车道结论"></section>
<section><h2>1. 实际输入不是49个充分不同的视角</h2><p>训练仅使用FRONT raw89—137，跨度<b>{d['duration_seconds']:.3f}秒</b>。自车累计移动<b>{d['ego']['path_length_m']:.2f}m</b>；其中<b>{d['ego']['frames_within_0p1m_of_start']}/49帧</b>距初始位置不足0.1m，整体相机基线仅{d['ego']['camera_baseline_m']:.2f}m。重复训练30K不能产生新视角。</p><table><tr><th>车辆</th><th>实际所在侧</th><th>4.8秒内世界轨迹长度</th><th>身份mask有正像素</th></tr>{motion}</table><p>左侧对向车辆驶过约40—45m，许多固定路面在车到达前已经可见。自车道近处a37只移动6.85m，a6后方路面又被a37等车遮挡，曝光机会少得多。不能只比较相同屏幕像素，以下均追踪同一世界坐标路面。</p></section>
<section><h2>2. raw128：车身轮廓背后假定路面的曝光机会</h2><p>把真实车身mask像素的射线与实测路面平面相交，在49帧里检查同一位置是否入镜、是否被车辆mask或实际3D框遮挡。只统计前方4—90m且位于交通路面带的有效交点；<b>没有把车身当道路真值。</b></p><table><tr><th>身份</th><th>有效路面查询／body像素</th><th>49帧始终无曝光机会</th><th>至少3帧曝光机会</th><th>曝光帧数中位数</th></tr>{exposure}</table><p>a26是左侧近车；a18是左侧更远车辆，也被前车遮挡，因此“左侧全部可恢复”同样不成立。右侧a6与a37的可用观测明显更弱。mask外扩2像素后，a6/a37结论不变。</p><img src="frames/raw128_silhouette_exposure.png" alt="raw128完整画面，车身轮廓背后路面曝光机会：红色0帧，黄色1到2帧，绿色至少3帧"><p class="small">红：0帧；黄：1—2帧；绿：≥3帧。未着色的body像素未建立有效平面交点；不是已证实可见。颜色表示近似曝光机会，不是高斯owner。</p></section>
<section><h2>3. LiDAR也没有自动补齐自车道的路面</h2><p>另以各车raw128真实3D框的地面足迹采样，查询原始49帧LiDAR中平面附近、车辆框外的实测点。半径0.25m，统计不同源帧；它只说明物理几何支撑，不提供被遮挡路面RGB。</p><table><tr><th>车底足迹</th><th>曝光机会帧数中位数</th><th>无实测LiDAR支撑的采样点</th><th>LiDAR支撑源帧中位数</th></tr>{physical}</table><p>车底足迹与整个车身轮廓背后的路面查询是两种区域，分母不同，不能混用百分比。a37足迹后半部分露出的机会较多，而其车身轮廓背后的更远路面大部分仍被遮挡。</p></section>
<section><h2>4. 49帧裁窗丢失了一部分原始长序列的候选观测</h2><p>对原始199帧做了只读标定／位姿／真实车辆框射线检查，未将额外帧加入初始化、mask或训练。为可比性，本表两列都只用3D框检查。窗口外没有逐帧分割复核，因此是<b>乐观的几何候选曝光上界</b>，不是确认的干净道路真值。</p><table><tr><th>raw128车身背后路面</th><th>当前49帧：≥3次候选曝光</th><th>原始199帧：≥3次候选曝光</th><th>窗口外最佳单帧候选</th></tr>{longer}</table><p>“当前49帧没见过”不等于“整个原始数据从未见过”。a37的查询在长序列中都有至少3次几何候选；a6仍有35.2%查询连199帧都没有候选。后续应先复核这些真实观测，再决定是否需要补全，不能把未核对候选当成训练真值。</p><div class="grid">{''.join(f'<div><p>原始raw{raw}，当前训练窗外，完整画面</p><img src="frames/source_raw{raw}.jpg" alt="原始长序列raw{raw}完整画面"></div>' for raw in [138,160,198])}</div></section>
<section><h2>5. 仍不能把全部残影归为缺少观测</h2><p>在raw128至少有3次非车辆曝光机会的有效路面查询上，跨帧RGB中位数参考与静态输出的绝对RGB误差中位数：左侧a26为<b>1.33/255</b>，a37为<b>78.33/255</b>。参考只有近似平面配准，且a37多数只有3—6帧曝光，<b>不是配对真值或算法通过／失败阈值</b>；但它提示少量已曝光区域也没有被当前静态层可靠恢复。</p><p>另外，当前mask监督车身，并不把车辆投影阴影纳入删除目标。原生GN11静态外观会学习观测中的阴影，没有删车后重算物理阴影的通路。左侧保留黑影可以与车身分离成功同时发生，不能把黑影一概视为车辆几何未移除。</p></section>
<section><h2>完整画面核对</h2><label>原始帧 <select id="raw">{''.join(f'<option value="{r}" '+('selected' if r==128 else '')+f'>raw{r}</option>' for r in [89,107,128,137])}</select></label><div class="grid"><div><p>完整观测</p><img id="gt" alt="完整观测"></div><div><p>静态分支</p><img id="static" alt="完整静态分支"></div><div><p>动态集合</p><img id="dynamic" alt="完整动态集合"></div><div><p>真实车底足迹对应的路面曝光机会</p><img id="exposure" alt="完整画面路面查询"></div></div></section>
<section><h2>对当前A/B结论的影响</h2><p>A/B继续原预算训练，额外原始帧只用于本次诊断。后续质量结论分开记录：已有真实背景观测却仍重建错的区域、当前49帧缺观测的区域、以及未去除的投影阴影。B扩大身份范围检验车辆分离覆盖；它仍使用同一49帧，无法自动解决自车道缺观测。</p><p>更有信息量的下一步是复核长序列候选路面／补充真实可见视角，再单独处理确实从未观测的补全问题。当前没有启动新训练或生成式补全。</p><details><summary>审计边界与原始凭据</summary><p>实测平面拟合RMSE {d['ground_fit']['rmse_m']:.3f}m；路面非完全平面、标定与时间差、mask和车辆框误差均会影响数值。非车辆遮挡物未逐一射线检测，曝光机会不能等同于确认的路面GT。没有因果消融，无法宣称某因素占总误差的百分比。human_verdict=null。</p><p><a href="footprint_evidence.json">完整足迹统计</a> · <a href="silhouette_evidence.json">完整轮廓与199帧统计</a> · <a href="evidence_summary.json">精简汇总</a></p></details></section>
<script>const raw=document.getElementById('raw');function show(){{for(const key of ['gt','static','dynamic','exposure'])document.getElementById(key).src='frames/raw'+raw.value+'_'+key+'.png';}}raw.onchange=show;show();</script></main></html>'''
 if (O.parent/'gn11_static_duplicate_20261019/index.html').exists():
  page=page.replace('<h1>左右车道的差异：缺少道路观测是更有力的主导解释</h1>','<h1>左右车道的差异：道路观测证据与分离问题</h1><section><p><b>后续核查修订：</b>本页证明左右背景观测差异，不能据此断言车身已从静态彻底分离。raw129重复解释审计确认：静态分支仍可随时间运动，速度正则约束衰减后的特征，静态body的直接RGB梯度为0。原判断低估了分离约束的漏洞。<a href="../gn11_static_duplicate_20261019/index.html">查看实际源码、参数与完整画面证据</a>。</p></section>')
  page=page.replace('更符合证据的描述是：动态主体已承担车辆重建，但被遮挡路面没有可靠地重建出来；少数已有曝光机会的区域仍有明显误差，阴影也没有随车辆删除。','这些数据说明背景监督不足；它们没有验证静态与动态对车辆的排他分离。后续源码与参数审计已确认分离约束的漏洞，同时少数已有曝光机会的区域仍有明显误差，阴影也没有随车辆删除。')
  page=page.replace('这是主要解释的证据排序，不是因果贡献百分比，也不等于“所有Gaussian归属已经正确”。','没有因果消融，无法给观测不足与静态重复解释排序或分配贡献百分比，也没有证明所有Gaussian归属正确。')
 (O/'index.html').write_text(page,encoding='utf-8')
 entry=BASE/'index.html';text=entry.read_text(encoding='utf-8');link='<p><a href="road_observability_20261019/index.html">新增：左右车道道路观测、LiDAR支撑与原始199帧核查</a></p>'
 if 'road_observability_20261019/index.html' not in text:text=re.sub(r'(<h1>.*?</h1>)',lambda m:m.group(1)+link,text,count=1)
 entry.write_text(text,encoding='utf-8')
 print(json.dumps(dict(report=str(O/'index.html'),motion=d['ego'],silhouette=[{k:v for k,v in r.items() if k not in ['pixels_xy']} for r in s['rows']]),ensure_ascii=False))
